import {normalizePersonName, personnelDisplayLabel, sameNamePersonnel} from './personIdentity';

interface Props {state: FoundationState; service: LocalFoundationService; execute: FoundationExecutor; routeUrl?: string; onRouteChange?: (url: string) => void;}
type PersonnelTab = 'personal' | 'contact' | 'employment' | 'compensation' | 'banking' | 'emergency' | 'account' | 'documents' | 'assets' | 'history';
const EMPLOYMENT_TYPE_OPTIONS = ['تمام‌وقت', 'پاره‌وقت', 'قراردادی', 'پروژه‌ای', 'ساعتی', 'کارآموزی', 'مشاوره‌ای'];
const SALES_LEVELS: {id: SalesHierarchyLevel; label: string; shortLabel: string}[] = [
  {id: 'sales_vice', label: 'معاونت فروش', shortLabel: 'معاونت'},
  {id: 'sales_manager', label: 'مدیر فروش', shortLabel: 'مدیر'},
  {id: 'senior_supervisor', label: 'سرپرست ارشد فروش', shortLabel: 'سرپرست ارشد'},
  {id: 'sales_supervisor', label: 'سرپرست کال‌سنتر', shortLabel: 'سرپرست کال‌سنتر'},
  {id: 'seller', label: 'فروشنده', shortLabel: 'فروشنده'},
];
const SALES_CHANNELS: {id: SalesChannel; label: string}[] = [{id: 'call_center', label: 'کال‌سنتر'}, {id: 'branch', label: 'فروش شعبه'}, {id: 'field', label: 'فروش میدانی'}, {id: 'partner', label: 'شبکه پذیرندگان'}];
type PersonnelCategory = 'all' | 'sales' | 'changes' | 'incomplete';
const PERSONNEL_CATEGORIES = new Set<PersonnelCategory>(['all', 'sales', 'changes', 'incomplete']);
function personnelCategoryFromUrl(href = window.location.href): PersonnelCategory | undefined {
  try {
    const value = new URL(href).searchParams.get('category') as PersonnelCategory | null;
    return value && PERSONNEL_CATEGORIES.has(value) ? value : undefined;
  } catch { return undefined; }
}
function personnelCategoryUrl(href: string, category: PersonnelCategory) {
  const url = new URL(href);
  if (category === 'all') url.searchParams.delete('category');
  else url.searchParams.set('category', category);
  return `${url.pathname}${url.search}${url.hash}`;
}

export function PersonnelPage({state, service, execute, routeUrl = window.location.href, onRouteChange}: Props) {
  const mayViewPersonnel = can(state.activeUser, 'organization.personnel.view');
  const mayReviewChanges = can(state.activeUser, 'organization.personnel.changes.review');
  const mayViewIncomplete = state.activeUser.permissions.includes(PERSONNEL_DOCUMENT_PERMISSION_QUEUE);
  const directReportIds = useMemo(() => new Set(state.personnel.filter((person) => person.managerPersonnelId === state.activeUser.personnelId || person.salesSupervisorPersonnelId === state.activeUser.personnelId).map((person) => person.id)), [state.personnel, state.activeUser.personnelId]);
  const mayViewDirectReports = directReportIds.size > 0;
  const [query, setQuery] = useState(''); const [status, setStatus] = useState('all'); const [unitId, setUnitId] = useState('all'); const [positionId, setPositionId] = useState('all'); const [employmentType, setEmploymentType] = useState('all');
  const [category, setCategory] = useState<PersonnelCategory>(() => {
    const requested = personnelCategoryFromUrl(routeUrl);
    if (requested === 'changes' && mayReviewChanges) return requested;
    if (requested === 'incomplete' && mayViewIncomplete) return requested;
    if ((requested === 'all' || requested === 'sales') && (mayViewPersonnel || mayViewDirectReports)) return requested;
    return mayViewPersonnel || mayViewDirectReports ? 'all' : mayViewIncomplete ? 'incomplete' : 'changes';
  }); const [salesLevel, setSalesLevel] = useState('all'); const [salesBranchId, setSalesBranchId] = useState('all');
  const [editing, setEditing] = useState<PersonnelRecord | 'new' | null>(null); const [editingTab, setEditingTab] = useState<PersonnelTab>('employment'); const [accountFor, setAccountFor] = useState<PersonnelRecord | null>(null); const [statusUser, setStatusUser] = useState<{personnel: PersonnelRecord; status: UserStatus} | null>(null); const [movementFor, setMovementFor] = useState<{personnel: PersonnelRecord; kind: PersonnelMovementKind} | null>(null);
  const [endingFor, setEndingFor] = useState<PersonnelRecord | null>(null); const [rehiringFor, setRehiringFor] = useState<PersonnelRecord | null>(null); const [cancelEndingFor, setCancelEndingFor] = useState<PersonnelRecord | null>(null);
  const mayManage = can(state.activeUser, 'organization.personnel.manage');
  const mayExport = can(state.activeUser, 'foundation.data.export') && mayViewPersonnel;
  const mayExportBanking = can(state.activeUser, 'organization.personnel.banking.view');
  const employmentTypes = [...new Set(state.personnel.map((item) => item.employmentType))];
  const positionFilterOptions = positionsForUnit(state.positions, unitId === 'all' ? undefined : unitId);
  const salesPersonnel = useMemo(() => state.personnel.filter((item) => isSalesPersonnel(item, state)), [state.personnel, state.units]);
  const incompletePersonnelCount = useMemo(() => state.personnel.filter((item) => item.employmentStatus !== 'ended' && mayViewPersonnelCompletion(state.activeUser, item, state.users) && !personnelCompletionSummary(item, state.operationalRecords).complete).length, [state]);
  const visible = useMemo(() => state.personnel.filter((item) => {
    const branchScope = salesBranchNamesForPersonnel(item, state).join(' ');
    const haystack = `${item.firstName} ${item.lastName} ${item.personnelCode} ${item.nationalId ?? ''} ${item.primaryMobile} ${branchScope}`.toLocaleLowerCase('fa');
    const withinScope = mayViewPersonnel || mayReviewChanges || directReportIds.has(item.id);
    return withinScope && haystack.includes(query.trim().toLocaleLowerCase('fa')) && (status === 'all' || item.employmentStatus === status) && (category !== 'sales' || isSalesPersonnel(item, state)) && (category === 'sales' ? (salesLevel === 'all' || item.salesHierarchyLevel === salesLevel) && (salesBranchId === 'all' || salesBranchUnitIdsForPersonnel(item, state).includes(salesBranchId)) : (unitId === 'all' || item.unitId === unitId) && (positionId === 'all' || item.positionId === positionId) && (employmentType === 'all' || item.employmentType === employmentType));
  }), [state, query, status, category, salesLevel, salesBranchId, unitId, positionId, employmentType, mayViewPersonnel, mayReviewChanges, directReportIds]);
  const sortColumns = useMemo<SortColumn<PersonnelRecord>[]>(() => [
    {key: 'person', kind: 'text', value: (item) => `${item.firstName} ${item.lastName}`},
    {key: 'unit', kind: 'text', value: (item) => state.units.find((unit) => unit.id === item.unitId)?.name},
    {key: 'position', kind: 'text', value: (item) => state.positions.find((position) => position.id === item.positionId)?.title},
    {key: 'branch', kind: 'text', value: (item) => state.units.find((unit) => unit.id === item.branchUnitId)?.name},
    {key: 'employment', kind: 'text', value: (item) => item.employmentType},
    {key: 'account', kind: 'text', value: (item) => state.users.find((user) => user.id === item.linkedUserId)?.username},
    {key: 'status', kind: 'text', value: (item) => employmentStatusLabel(item.employmentStatus)},
    {key: 'salesLevel', kind: 'text', value: (item) => salesLevelLabel(item.salesHierarchyLevel)},
    {key: 'salesChannel', kind: 'text', value: (item) => salesChannelLabel(item.salesChannel)},
    {key: 'salesSupervisor', kind: 'text', value: (item) => personnelName(state, item.salesSupervisorPersonnelId)},
    {key: 'salesBranch', kind: 'text', value: (item) => salesBranchNamesForPersonnel(item, state).join('، ')},
  ], [state.units, state.positions, state.users, state.personnel]);
  const {sortedRows: sortedPersonnel, sort, requestSort} = useSortableRows(visible, sortColumns, 'person', 'asc');
  const replaceCategoryInRoute = useCallback((nextCategory: PersonnelCategory) => {
    const nextUrl = personnelCategoryUrl(routeUrl, nextCategory);
    if (onRouteChange) onRouteChange(nextUrl);
    else window.history.replaceState(window.history.state, '', nextUrl);
  }, [onRouteChange, routeUrl]);
  useEffect(() => {
    if (!mayViewPersonnel && !mayViewDirectReports && mayViewIncomplete && category !== 'incomplete') {setCategory('incomplete');return;}
    if (!mayViewPersonnel && !mayViewDirectReports && !mayViewIncomplete && mayReviewChanges && category !== 'changes') {setCategory('changes');return;}
    if (!mayReviewChanges && category === 'changes') {setCategory('all');}
    if (!mayViewIncomplete && category === 'incomplete') {setCategory('all');}
  }, [mayViewPersonnel, mayViewDirectReports, mayReviewChanges, mayViewIncomplete, category]);
  useEffect(() => { replaceCategoryInRoute(category); }, [category, replaceCategoryInRoute]);
  return <div className="page-stack personnel-page">
    <section className="page-intro org-page-intro"><span className="page-intro-icon"><ContactRound size={24} /></span><div><span>سازمان / پرسنل</span><h2>پرسنل سازمان</h2><p>پرونده شغلی افراد مستقل از حساب کاربری نگهداری می‌شود؛ پایان همکاری یا غیرفعال‌شدن حساب هیچ رکوردی را حذف نمی‌کند.</p></div>{(mayExport || mayManage) && <div className="page-intro-action action-cluster">{mayExport && <button className="button button--secondary" title="خروجی جامع همه پرسنل و تاریخچه گردش" onClick={() => void execute('personnel-export', async () => {const result = await downloadPersonnelWorkbook(state, mayExportBanking); return service.recordPersonnelExport(result.personnelCount, result.movementCount, result.includesBanking);}, 'فایل Excel جامع پرسنل دریافت و رویداد آن در ممیزی ثبت شد.')}><Download size={18} /> خروجی پرسنل</button>}{mayManage && <button className="org-primary-action" onClick={() => {setEditingTab('personal');setEditing('new');}}><Plus size={18} /> پرسنل جدید</button>}</div>}</section>
    <div className="personnel-category-tabs" role="tablist" aria-label="دسته‌بندی پرسنل">{mayViewPersonnel && <button role="tab" aria-selected={category === 'all'} className={category === 'all' ? 'active' : ''} onClick={() => setCategory('all')}><UsersRound size={18}/><span><strong>همه پرسنل</strong><small>{state.personnel.length.toLocaleString('en-US')} پرونده سازمانی</small></span></button>}{mayViewPersonnel && <button role="tab" aria-selected={category === 'sales'} className={category === 'sales' ? 'active' : ''} onClick={() => setCategory('sales')}><Crown size={18}/><span><strong>پرسنل فروش</strong><small>{salesPersonnel.length.toLocaleString('en-US')} عضو شبکه فروش</small></span></button>}{mayViewIncomplete && <button role="tab" aria-selected={category === 'incomplete'} className={category === 'incomplete' ? 'active' : ''} onClick={() => setCategory('incomplete')}><Files size={18}/><span><strong>نواقص پرونده</strong><small>{incompletePersonnelCount.toLocaleString('en-US')} نیازمند تکمیل</small></span></button>}{mayReviewChanges && <button role="tab" aria-selected={category === 'changes'} className={category === 'changes' ? 'active' : ''} onClick={() => setCategory('changes')}><ClipboardCheck size={18}/><span><strong>صف تغییرات</strong><small>{state.personnelProfileChangeRequests.filter((request) => request.status === 'submitted').length.toLocaleString('en-US')} در انتظار بررسی</small></span></button>}</div>
    {category === 'changes' ? <PersonnelChangeQueue state={state} service={service} execute={execute}/> : category === 'incomplete' ? <PersonnelIncompleteQueue state={state} onOpen={(personnel) => {setEditingTab('documents');setEditing(personnel);}}/> : <>
    <section className="org-metrics personnel-metrics"><Metric value={category === 'sales' ? salesPersonnel.length : state.personnel.length} label={category === 'sales' ? 'پرسنل فروش' : 'کل پرسنل'} icon={<UsersRound size={19} />} /><Metric value={(category === 'sales' ? salesPersonnel : state.personnel).filter((item) => item.employmentStatus === 'active').length} label="همکاری فعال" icon={<BadgeCheck size={19} />} /><Metric value={(category === 'sales' ? salesPersonnel : state.personnel).filter((item) => item.employmentStatus === 'ended').length} label="خاتمه همکاری" icon={<CircleAlert size={19} />} /><Metric value={(category === 'sales' ? salesPersonnel : state.personnel).filter((item) => item.linkedUserId).length} label="دارای حساب" icon={<KeyRound size={19} />} /></section>
    {category === 'sales' && <SalesHierarchyOverview personnel={salesPersonnel} selected={salesLevel} onSelect={setSalesLevel} />}
    <section className="org-panel personnel-list-panel">
      <div className={`customer-toolbar ${category === 'sales' ? 'sales-personnel-toolbar' : ''}`}><label className="search-box"><Search size={18} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="جست‌وجوی نام، کد پرسنلی، کد ملی یا همراه" /></label><select aria-label="وضعیت همکاری" value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">همه وضعیت‌ها</option><option value="active">فعال</option><option value="ending_scheduled">پایان زمان‌بندی‌شده</option><option value="ended">خاتمه‌یافته</option><option value="rehire_scheduled">بازگشت زمان‌بندی‌شده</option></select>{category === 'sales' ? <><select aria-label="رده فروش" value={salesLevel} onChange={(event) => setSalesLevel(event.target.value)}><option value="all">همه رده‌های فروش</option>{SALES_LEVELS.map((level) => <option key={level.id} value={level.id}>{level.label}</option>)}</select><select aria-label="شعبه فروش" value={salesBranchId} onChange={(event) => setSalesBranchId(event.target.value)}><option value="all">همه شعبه‌های فروش</option>{state.units.filter((unit) => unit.type === 'شعبه').map((unit) => <option key={unit.id} value={unit.id}>{unit.name}</option>)}</select></> : <><select aria-label="واحد سازمانی" value={unitId} onChange={(event) => {const next=event.target.value;setUnitId(next);if(positionId!=='all'&&!positionsForUnit(state.positions,next==='all'?undefined:next).some((position)=>position.id===positionId))setPositionId('all');}}><option value="all">همه واحدها</option>{state.units.filter((unit) => unit.type !== 'شعبه').map((unit) => <option key={unit.id} value={unit.id}>{unit.name}</option>)}</select><select aria-label="سمت سازمانی" value={positionId} onChange={(event) => setPositionId(event.target.value)}><option value="all">همه سمت‌ها</option>{(unitId==='all'?state.positions:positionFilterOptions).map((position) => <option key={position.id} value={position.id}>{position.title}</option>)}</select><select aria-label="نوع همکاری" value={employmentType} onChange={(event) => setEmploymentType(event.target.value)}><option value="all">همه نوع همکاری</option>{employmentTypes.map((type) => <option key={type}>{type}</option>)}</select></>}</div>
      <div className={`enterprise-table ${category === 'sales' ? 'sales-personnel-table' : 'personnel-table'}`}>
        {category === 'sales' ? <div className="enterprise-table-head"><span><SortHeader columnKey="person" label="پرسنل فروش" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="salesLevel" label="رده فروش" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="salesChannel" label="کانال فروش" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="salesSupervisor" label="سرپرست فروش" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="salesBranch" label="شعبه فروش / تحت مدیریت" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="status" label="وضعیت" sort={sort} onSort={requestSort}/></span><span>اقدام‌ها</span></div> : <div className="enterprise-table-head"><span><SortHeader columnKey="person" label="پرسنل" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="unit" label="واحد سازمانی" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="position" label="سمت سازمانی" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="branch" label="شعبه استقرار" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="employment" label="نوع همکاری" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="account" label="حساب کاربری" sort={sort} onSort={requestSort}/></span><span><SortHeader columnKey="status" label="وضعیت" sort={sort} onSort={requestSort}/></span><span>اقدام‌ها</span></div>}
        {sortedPersonnel.map((person) => {const user = state.users.find((item) => item.id === person.linkedUserId); const hasSimilarName = sameNamePersonnel(person,state.personnel).length > 0; return <article key={person.id} className="enterprise-table-row"><button className="record-identity" onClick={() => setEditing(person)}><span className="record-avatar">{person.firstName[0]}{person.lastName[0]}</span><span><strong>{person.firstName} {person.lastName}</strong><small>کد پرسنلی {person.personnelCode}</small>{hasSimilarName&&<em className="identity-name-warning">نام مشابه؛ شناسه را بررسی کنید</em>}</span></button>{category === 'sales' ? <><span><b>{salesLevelLabel(person.salesHierarchyLevel) || 'تعیین نشده'}</b></span><span><b>{salesChannelLabel(person.salesChannel) || '—'}</b></span><span><b>{personnelName(state, person.salesSupervisorPersonnelId) || 'بالاترین رده'}</b></span><span><SalesBranchScopeCell personnel={person} state={state}/></span></> : <><span><b>{state.units.find((item) => item.id === person.unitId && item.type !== 'شعبه')?.name ?? '—'}</b></span><span><b>{state.positions.find((item) => item.id === person.positionId)?.title ?? '—'}</b></span><span><b>{state.units.find((item) => item.id === person.branchUnitId && item.type === 'شعبه')?.name ?? 'تعیین نشده'}</b></span><span>{person.employmentType}</span><span>{user ? <><b>{user.username}</b><small>{user.roles.join('، ')}</small></> : <small>بدون حساب</small>}</span></>}<span><i className={`status-badge status-badge--${person.employmentStatus === 'active' ? 'active' : 'inactive'}`}>{person.employmentStatus === 'active' ? 'فعال' : 'خاتمه‌یافته'}</i></span><div className="user-actions"><Icon label="مشاهده و ویرایش پرونده" tone="primary" onClick={() => setEditing(person)}><Pencil size={17} /></Icon>{person.employmentStatus === 'active' && mayManage && <Icon label="ثبت تغییر واحد، سمت یا انتقال شعبه" tone="qa" onClick={() => {setEditing(person);}}><ArrowLeftRight size={17} /></Icon>}{!user && person.employmentStatus === 'active' && can(state.activeUser, 'organization.personnel.account.manage') && <Icon label="ایجاد حساب کاربری" tone="qa" onClick={() => setAccountFor(person)}><UserPlus size={17} /></Icon>}{user && can(state.activeUser, 'foundation.users.status.manage') && !user.isAdmin && <Icon label={user.status === 'active' ? 'غیرفعال‌سازی حساب کاربری' : 'فعال‌سازی حساب کاربری'} tone={user.status === 'active' ? 'danger' : 'success'} onClick={() => setStatusUser({personnel: person, status: user.status === 'active' ? 'inactive' : 'active'})}><Power size={17} /></Icon>}</div></article>;})}
        {!sortedPersonnel.length && <div className="table-empty"><Search size={22} /><strong>پرسنلی با این فیلتر پیدا نشد</strong><span>عبارت جست‌وجو یا فیلترها را تغییر دهید.</span></div>}
      </div>
    </section>
    {(mayManage || mayViewDirectReports) && <PersonnelLifecyclePanel personnel={mayManage ? sortedPersonnel : sortedPersonnel.filter((person) => directReportIds.has(person.id))} state={state} mayManage={mayManage} onEnd={setEndingFor} onCancelEnd={setCancelEndingFor} onRehire={setRehiringFor}/>}
    </>}
    {editing && <PersonnelDialog initialTab={editingTab} record={editing === 'new' ? undefined : editing} state={state} service={service} execute={execute} onClose={() => {setEditing(null);setEditingTab('employment');}} onCreateAccount={(person) => {setEditing(null); setAccountFor(person);}} onAssignmentChange={(person, kind) => {setEditing(null); setEditingTab('employment'); setMovementFor({personnel: person, kind});}} onEndEmployment={(person) => {setEditing(null);setEndingFor(person);}} onCancelEnd={(person) => {setEditing(null);setCancelEndingFor(person);}} onRehire={(person) => {setEditing(null);setRehiringFor(person);}} onAddCompensation={(input) => editing !== 'new' ? execute('sales-compensation-save', () => service.addSalesCompensation(editing.id, input), 'نسخه جدید شرایط حقوق و پورسانت ثبت شد.').then((succeeded) => {if (succeeded) {setEditing(null);setEditingTab('employment');}}) : Promise.resolve(true)} onSubmit={(input) => execute('personnel-save', () => editing === 'new' ? service.createPersonnel(input) : service.updatePersonnel(editing.id, editing.updatedAt, input), editing === 'new' ? 'پرونده پرسنلی ایجاد شد.' : 'پرونده پرسنلی به‌روزرسانی شد.').then((succeeded) => {if (succeeded) {setEditing(null);setEditingTab('employment');}})} />}
    {movementFor && <AssignmentChangeDialog personnel={movementFor.personnel} kind={movementFor.kind} state={state} onClose={() => setMovementFor(null)} onSubmit={(input) => execute('personnel-movement', () => service.changePersonnelAssignment(movementFor.personnel.id, input), input.kind === 'sales_transfer' ? 'انتقال فروشنده و مسیر جدید او با تاریخ ثبت شد.' : input.kind === 'branch_transfer' ? 'انتقال شعبه با تاریخ‌های استقرار ثبت شد.' : input.kind === 'unit_change' ? 'تغییر واحد در پرونده ثبت شد.' : 'تغییر سمت در پرونده ثبت شد.').then((succeeded) => {if (succeeded) setMovementFor(null);})} />}
    {accountFor && <AccountDialog person={accountFor} state={state} onClose={() => setAccountFor(null)} onSubmit={(input) => execute('personnel-account', () => service.createUserForPersonnel(accountFor.id, input), 'حساب کاربری ساخته و به پرونده پرسنلی متصل شد.').then((succeeded) => {if (succeeded) setAccountFor(null);})} />}
{statusUser && <ConfirmDialog title={statusUser.status === 'inactive' ? 'غیرفعال‌سازی حساب کاربری' : 'فعال‌سازی حساب کاربری'} text={`${statusUser.status === 'inactive' ? 'دسترسی سامانه' : 'حساب کاربری'} «${personnelDisplayLabel(statusUser.personnel,state)}» ${statusUser.status === 'inactive' ? 'متوقف می‌شود؛ پرونده پرسنلی باقی می‌ماند.' : 'دوباره فعال می‌شود.'}`} confirm={statusUser.status === 'inactive' ? 'تأیید غیرفعال‌سازی' : 'فعال‌سازی حساب'} danger={statusUser.status === 'inactive'} onClose={() => setStatusUser(null)} onConfirm={() => {const user = state.users.find((item) => item.id === statusUser.personnel.linkedUserId)!; execute('personnel-user-status', () => service.setUserStatus(user.id, userConcurrencyToken(user), statusUser.status), 'وضعیت حساب کاربری تغییر کرد.').then((succeeded) => {if (succeeded) setStatusUser(null);});}} />}
    {endingFor && (
      <PersonnelEndDialog
        personnel={endingFor}
        state={state}
        onClose={() => setEndingFor(null)}
        onSubmit={(input) => execute('personnel-end-request', () => service.submitPersonnelEndRequest(endingFor.id, input), 'درخواست برای بررسی منابع انسانی ارسال شد؛ وضعیت همکاری، حساب و پنل فرد بدون تغییر باقی ماند.').then((succeeded) => {if (succeeded) setEndingFor(null);})}
      />
    )}
    {cancelEndingFor && (
      <ReasonDialog
        title="پس‌گرفتن درخواست پایان همکاری"
        description="تا پیش از اجرای نهایی خروج می‌توانید درخواست را پس بگیرید. لغو درخواست در تاریخچه غیرقابل حذف باقی می‌ماند و حساب فرد فعال می‌ماند."
        confirm="تأیید لغو درخواست"
        onClose={() => setCancelEndingFor(null)}
        onSubmit={(reason) => execute('personnel-end-request-cancel', () => service.cancelPersonnelEndRequest(cancelEndingFor.id, reason, openPersonnelEndRequest(state, cancelEndingFor.id)?.version), 'درخواست پایان همکاری لغو شد؛ وضعیت پنل و حساب فرد بدون تغییر باقی ماند.').then((succeeded) => {if (succeeded) setCancelEndingFor(null);})}
      />
    )}
    {rehiringFor && (
      <PersonnelRehireDialog
        personnel={rehiringFor}
        state={state}
        onClose={() => setRehiringFor(null)}
        onSubmit={(input) => execute('personnel-rehire', () => service.rehirePersonnel(rehiringFor.id, rehiringFor.updatedAt, input), input.effectiveDate === todayIsoDate() ? 'دوره همکاری جدید آغاز و حساب با نقش‌های جدید فعال شد.' : 'بازگشت به همکاری زمان‌بندی شد.').then((succeeded) => {if (succeeded) setRehiringFor(null);})}
      />
    )}
  </div>;
}

function PersonnelLifecyclePanel({personnel, state, mayManage, onEnd, onCancelEnd, onRehire}: {personnel: PersonnelRecord[]; state: FoundationState; mayManage: boolean; onEnd: (person: PersonnelRecord) => void; onCancelEnd: (person: PersonnelRecord) => void; onRehire: (person: PersonnelRecord) => void}) {
  return <details className="org-panel personnel-lifecycle-panel">
    <summary><span><CalendarClock size={20}/><strong>مدیریت پایان همکاری و بازگشت به کار</strong></span><small>همه اقدامات تاریخ‌دار، قابل ممیزی و بدون حذف پرونده هستند.</small></summary>
    <div className="personnel-lifecycle-list">{personnel.map((person) => {const request = openPersonnelEndRequest(state, person.id); return <article key={person.id}>
      <div><strong>{person.firstName} {person.lastName}</strong><small>{person.personnelCode} · {request?.status === 'requested' ? 'در انتظار بررسی منابع انسانی؛ بدون اثر بر حساب' : request?.status === 'scheduled' ? `تأییدشده؛ اجرا در ${formatPersianDate(String(request.payload.proposedEmploymentEndDate ?? ''))}` : employmentStatusLabel(person.employmentStatus)}{!request && person.pendingLifecycleChange ? ` · اجرا در ${formatPersianDate(person.pendingLifecycleChange.effectiveDate)}` : ''}</small></div>
      <div className="user-actions">
        {person.employmentStatus === 'active' && !request && <Icon label="ثبت درخواست بررسی پایان همکاری" tone="danger" onClick={() => onEnd(person)}><LogOut size={17}/></Icon>}
        {request && ['requested', 'scheduled'].includes(request.status) && (request.createdByUserId === state.activeUser.id || mayManage) && <Icon label="پس‌گرفتن درخواست پایان همکاری" tone="success" onClick={() => onCancelEnd(person)}><RotateCcw size={17}/></Icon>}
        {person.employmentStatus === 'ended' && mayManage && <Icon label="ثبت بازگشت به همکاری" tone="qa" onClick={() => onRehire(person)}><UserRoundCheck size={17}/></Icon>}
        {person.employmentStatus === 'rehire_scheduled' && <span className="status-badge status-badge--pending">بازگشت در انتظار اجرا</span>}
      </div>
    </article>;})}</div>
  </details>;
}

function PersonnelLifecycleInlineActions({personnel, onEnd, onCancelEnd, onRehire}: {personnel: PersonnelRecord; onEnd: () => void; onCancelEnd: () => void; onRehire: () => void}) {
  return <section className="personnel-lifecycle-inline">
    <div><CalendarClock size={20}/><span><strong>چرخه همکاری</strong><small>وضعیت همکاری و تاریخ پایان فقط از این فرایند تغییر می‌کند و در سابقه باقی می‌ماند.</small></span></div>
    <div className="personnel-lifecycle-inline__actions">
      {personnel.employmentStatus === 'active' && <button type="button" className="button button--danger" onClick={onEnd}><LogOut size={17}/> ثبت درخواست بررسی پایان همکاری</button>}
      {personnel.employmentStatus === 'ending_scheduled' && <button type="button" className="button button--secondary" onClick={onCancelEnd}><RotateCcw size={17}/> لغو پایان زمان‌بندی‌شده</button>}
      {personnel.employmentStatus === 'ended' && <button type="button" className="button button--primary" onClick={onRehire}><UserRoundCheck size={17}/> ثبت بازگشت به همکاری</button>}
      {personnel.employmentStatus === 'rehire_scheduled' && <span className="status-badge status-badge--pending">بازگشت به همکاری زمان‌بندی شده است</span>}
    </div>
  </section>;
}

function PersonnelEndDialog({personnel, state, onClose, onSubmit}: {personnel: PersonnelRecord; state: FoundationState; onClose: () => void; onSubmit: (input: PersonnelEndInput) => void}) {
  const [departureInitiator, setDepartureInitiator] = useState<'' | PersonnelEndInput['departureInitiator']>(''); const [effectiveDate, setEffectiveDate] = useState(todayIsoDate()); const [reason, setReason] = useState(''); const [handoffNotes, setHandoffNotes] = useState(''); const [errors, setErrors] = useState<string[]>([]);
  const submit = () => {const next = validateRequired([{label: 'نوع پایان همکاری', value: departureInitiator}, {label: 'تاریخ پایان همکاری', value: effectiveDate}, {label: 'شرح و دلیل', value: reason, valid: (value) => String(value ?? '').trim().length >= 3, message: 'شرح و دلیل پایان همکاری باید حداقل ۳ نویسه باشد.'}]); setErrors(next); if (!next.length && departureInitiator) onSubmit({effectiveDate, departureInitiator, reason: reason.trim(), handoffNotes: handoffNotes.trim() || undefined});};
  return <Modal onClose={onClose}><div className="modal-heading"><span className="modal-kicker">درخواست مدیریتی</span><h2>درخواست بررسی پایان همکاری {personnelDisplayLabel(personnel,state)}</h2><p>این ثبت فقط یک درخواست برای منابع انسانی می‌سازد. تا زمان تأیید و اجرای نهایی، وضعیت همکاری، نقش‌ها، حقوق، حساب و پنل این فرد هیچ تغییری نمی‌کند.</p></div><FormValidationSummary errors={errors}/><FormGrid><Field label="نوع درخواست" full required><select aria-required="true" value={departureInitiator} onChange={(event) => setDepartureInitiator(event.target.value as typeof departureInitiator)}><option value="">انتخاب کنید</option><option value="employee">اعلام استعفا / عدم تمایل پرسنل به ادامه همکاری</option><option value="organization">درخواست سازمان برای بررسی قطع همکاری</option></select></Field><Field label="تاریخ پیشنهادی پایان همکاری" required><PersianDateInput value={effectiveDate} required min={todayIsoDate()} onChange={setEffectiveDate} ariaLabel="تاریخ شمسی پیشنهادی پایان همکاری"/></Field><Field label={departureInitiator === 'employee' ? 'شرح اعلام استعفا' : departureInitiator === 'organization' ? 'دلیل درخواست بررسی قطع همکاری' : 'شرح و دلیل درخواست'} full required><textarea value={reason} onChange={(event) => setReason(event.target.value)} placeholder={departureInitiator === 'employee' ? 'شرح اعلام‌شده از سوی پرسنل و شرایط پیگیری' : 'شرح مستند موضوع برای بررسی منابع انسانی'}/></Field><Field label="یادداشت اولیه برای تحویل کار و اموال" full><textarea value={handoffNotes} onChange={(event) => setHandoffNotes(event.target.value)} placeholder="در این مرحله فقط برای اطلاع منابع انسانی ثبت می‌شود"/></Field></FormGrid><div className="waiting-banner"><CircleAlert size={19}/><div><span>بدون اثر عملیاتی</span><strong>ارسال این فرم حساب کاربر را نمی‌بندد و دسترسی یا وضعیت همکاری او را تغییر نمی‌دهد.</strong></div></div><div className="dialog-actions"><button className="button button--secondary" onClick={onClose}>انصراف</button><button className="button button--primary" onClick={submit}><LogOut size={17}/> ارسال برای بررسی منابع انسانی</button></div></Modal>;
}

function openPersonnelEndRequest(state: FoundationState, personnelId: string): OperationalRecord | undefined {
  return state.operationalRecords.find((record) => record.moduleId === 'offboarding' && record.ownerPersonnelId === personnelId && ['requested', 'scheduled'].includes(record.status));
}

function ReasonDialog({title, description, confirm, onClose, onSubmit}: {title: string; description: string; confirm: string; onClose: () => void; onSubmit: (reason: string) => void}) {
  const [reason, setReason] = useState(''); const [error, setError] = useState('');
  return <Modal onClose={onClose}><div className="modal-heading"><h2>{title}</h2><p>{description}</p></div>{error && <FormValidationSummary errors={[error]}/>}<Field label="دلیل اقدام" full required><textarea value={reason} onChange={(event) => setReason(event.target.value)} /></Field><div className="dialog-actions"><button className="button button--secondary" onClick={onClose}>انصراف</button><button className="button button--primary" onClick={() => {if (reason.trim().length < 3) {setError('دلیل اقدام باید حداقل ۳ نویسه باشد.'); return;} onSubmit(reason.trim());}}>{confirm}</button></div></Modal>;
}

function PersonnelRehireDialog({personnel, state, onClose, onSubmit}: {personnel: PersonnelRecord; state: FoundationState; onClose: () => void; onSubmit: (input: PersonnelRehireInput) => void}) {
  const [effectiveDate, setEffectiveDate] = useState(todayIsoDate()); const [reason, setReason] = useState(''); const [employmentType, setEmploymentType] = useState(personnel.employmentType); const [unitId, setUnitId] = useState(personnel.unitId); const [positionId, setPositionId] = useState(personnel.positionId); const [branchUnitId, setBranchUnitId] = useState(personnel.branchUnitId ?? ''); const [managerPersonnelId, setManagerPersonnelId] = useState(personnel.managerPersonnelId ?? ''); const [roleIds, setRoleIds] = useState<string[]>([]); const [roleQuery, setRoleQuery] = useState(''); const [errors, setErrors] = useState<string[]>([]);
  const roles = state.roles.filter((role) => role.status === 'active' && `${role.name} ${role.description}`.toLocaleLowerCase('fa').includes(roleQuery.trim().toLocaleLowerCase('fa')));
  const linkedUser = state.users.find((user) => user.id === personnel.linkedUserId);
  const availablePositions = positionsForUnit(state.positions, unitId, personnel.positionId).filter((position) => position.status === 'active' || position.id === personnel.positionId);
  const changeUnit = (nextUnitId: string) => {setUnitId(nextUnitId); const current = state.positions.find((position) => position.id === positionId); if (!current || !positionSupportsUnit(current, nextUnitId)) setPositionId('');};
  const submit = () => {const next = validateRequired([{label: 'تاریخ شروع دوره جدید', value: effectiveDate}, {label: 'دلیل بازگشت', value: reason}, {label: 'نوع همکاری', value: employmentType}, {label: 'واحد سازمانی', value: unitId}, {label: 'سمت سازمانی', value: positionId}, ...(linkedUser ? [{label: 'حداقل یک نقش جدید', value: roleIds, valid: (value) => Array.isArray(value) && value.length > 0, message: 'برای فعال‌شدن حساب، حداقل یک نقش جدید انتخاب کنید.'}] : [])]); setErrors(next); if (!next.length) onSubmit({effectiveDate, reason: reason.trim(), employmentType, unitId, positionId, branchUnitId: branchUnitId || undefined, managerPersonnelId: managerPersonnelId || undefined, roleIds});};
  return <Modal onClose={onClose}><div className="modal-heading"><span className="modal-kicker">دوره همکاری جدید</span><h2>بازگشت به همکاری {personnelDisplayLabel(personnel,state)}</h2><p>کد پرسنلی و پرونده قبلی حفظ می‌شود؛ نقش‌های قدیمی خودکار برنمی‌گردند.</p></div><FormValidationSummary errors={errors}/><FormGrid><Field label="تاریخ شروع دوره جدید" required><PersianDateInput value={effectiveDate} required min={todayIsoDate()} onChange={setEffectiveDate} ariaLabel="تاریخ شمسی بازگشت به کار"/></Field><Field label="نوع همکاری" required><select value={employmentType} onChange={(event) => setEmploymentType(event.target.value)}>{EMPLOYMENT_TYPE_OPTIONS.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="واحد سازمانی" required><select value={unitId} onChange={(event) => changeUnit(event.target.value)}>{state.units.filter((unit) => unit.status === 'active' && unit.type !== 'شعبه').map((unit) => <option key={unit.id} value={unit.id}>{unit.name}</option>)}</select></Field><Field label="سمت سازمانی" required><select value={positionId} disabled={!unitId} onChange={(event) => setPositionId(event.target.value)}><option value="">{unitId?'انتخاب سمت مجاز این واحد':'ابتدا واحد را انتخاب کنید'}</option>{availablePositions.map((position) => <option key={position.id} value={position.id}>{position.title}</option>)}</select></Field><Field label="شعبه استقرار"><select value={branchUnitId} onChange={(event) => setBranchUnitId(event.target.value)}><option value="">تعیین نشده</option>{state.units.filter((unit) => unit.status === 'active' && unit.type === 'شعبه').map((unit) => <option key={unit.id} value={unit.id}>{unit.name}</option>)}</select></Field><Field label="مدیر مستقیم"><select value={managerPersonnelId} onChange={(event) => setManagerPersonnelId(event.target.value)}><option value="">تعیین نشده</option>{state.personnel.filter((item) => item.id !== personnel.id && item.employmentStatus === 'active').map((item) => <option key={item.id} value={item.id}>{personnelDisplayLabel(item,state)}</option>)}</select></Field><Field label="دلیل بازگشت" full required><textarea value={reason} onChange={(event) => setReason(event.target.value)} /></Field></FormGrid>{linkedUser && <section className="rehire-role-picker"><div><strong>نقش‌های دوره جدید</strong><small>انتخاب صریح لازم است؛ دسترسی‌های دوره قبلی بازیابی نمی‌شوند.</small></div><label className="search-box"><Search size={17}/><input value={roleQuery} onChange={(event) => setRoleQuery(event.target.value)} placeholder="جست‌وجوی نقش"/></label><div className="rehire-role-picker__list">{roles.map((role) => <label key={role.id}><input type="checkbox" checked={roleIds.includes(role.id)} onChange={(event) => setRoleIds((current) => event.target.checked ? [...current, role.id] : current.filter((id) => id !== role.id))}/><span><strong>{role.name}</strong><small>{role.description}</small></span></label>)}</div></section>}<div className="dialog-actions"><button className="button button--secondary" onClick={onClose}>انصراف</button><button className="button button--primary" onClick={submit}><UserRoundCheck size={17}/> ثبت بازگشت به کار</button></div></Modal>;
}
function SalesCompensationInitialPreview({level}: {level?: SalesHierarchyLevel}) {
  const defaults = defaultSalesCompensation(level);
  if (!defaults) return <div className="compensation-empty"><BadgeDollarSign size={24}/><div><strong>برای این رده شرایط پیش‌فرض تعیین نشده است</strong><p>پس از ایجاد پرونده می‌توانید یک نسخه تاریخ‌دار برای حقوق و پورسانت ثبت کنید.</p></div></div>;
  return <div className="compensation-initial-preview"><BadgeDollarSign size={24}/><div><strong>شرایط اولیه هنگام ایجاد پرونده ثبت می‌شود</strong><p>{salesCompensationModeLabel(defaults.mode)}{defaults.monthlyFixedSalaryRial ? ` · ${formatPortalAmount(defaults.monthlyFixedSalaryRial)} ریال در ماه` : ''}{defaults.commissionPercent ? ` · ${defaults.commissionPercent}٪ پورسانت` : ''}</p><small>مبنای پورسانت فعلاً «وصول فاکتور» ثبت می‌شود و فرمول محاسبه در مرحله بعد تعیین خواهد شد.</small></div></div>;
}

function SalesCompensationEditor({record, onSubmit}: {record: PersonnelRecord; onSubmit: (input: SalesCompensationInput) => Promise<unknown>}) {
  const latest = orderedSalesCompensationHistory(record)[0];
  const current = currentSalesCompensation(record);
  const fallback = defaultSalesCompensation(record.salesHierarchyLevel);
  const [mode, setMode] = useState<SalesCompensationInput['mode']>(latest?.mode ?? fallback?.mode ?? 'fixed_salary');
  const [salary, setSalary] = useState(latest?.monthlyFixedSalaryRial ?? fallback?.monthlyFixedSalaryRial ?? '');
  const [percent, setPercent] = useState(latest?.commissionPercent ?? fallback?.commissionPercent ?? '');
  const [effectiveFrom, setEffectiveFrom] = useState(todayIsoDate());
  const [reason, setReason] = useState('');
  const [errors, setErrors] = useState<string[]>([]);
  const fixedRequired = mode === 'fixed_salary' || mode === 'fixed_salary_plus_commission';
  const commissionRequired = mode === 'commission_only' || mode === 'fixed_salary_plus_commission';
  const submit = () => {
    const input: SalesCompensationInput = {mode, monthlyFixedSalaryRial: fixedRequired ? salary : undefined, commissionPercent: commissionRequired ? percent : undefined, effectiveFrom, reason};
    try {validateSalesCompensationInput(input);setErrors([]);void onSubmit(input);} catch (error) {setErrors([error instanceof Error ? error.message : 'اطلاعات شرایط مالی معتبر نیست.']);}
  };
  return <div className="sales-compensation-editor">
    <div className="compensation-current-card"><span><BadgeDollarSign size={22}/></span><div><small>شرایط جاری</small><strong>{current ? salesCompensationModeLabel(current.mode) : 'هنوز ثبت نشده'}</strong><p>{current?.monthlyFixedSalaryRial ? `${formatPortalAmount(current.monthlyFixedSalaryRial)} ریال حقوق ماهانه` : 'بدون حقوق ثابت'} · {current?.commissionPercent ? `${current.commissionPercent}٪ پورسانت` : 'بدون پورسانت'}</p></div>{current && <time>از {formatPersianDate(current.effectiveFrom)}</time>}</div>
    <div className="compensation-policy-note"><CircleAlert size={18}/><span>در این مرحله فقط درصد نگهداری می‌شود. مبنای ثبت‌شده «وصول فاکتور» است و موتور محاسبه پورسانت بعداً اضافه می‌شود.</span></div>
    <FormValidationSummary errors={errors}/>
    <FormGrid><Field label="نوع پرداخت" required><select value={mode} onChange={(event) => setMode(event.target.value as SalesCompensationInput['mode'])}><option value="fixed_salary">حقوق ثابت</option><option value="commission_only">فقط پورسانت</option><option value="fixed_salary_plus_commission">حقوق ثابت + پورسانت</option></select></Field>{fixedRequired && <Field label="حقوق ثابت ماهانه (ریال)" required><input dir="ltr" inputMode="numeric" value={salary ? formatPortalAmount(salary) : ''} onChange={(event) => setSalary(toLatinDigits(event.target.value).replace(/\D/g, ''))} placeholder="30,000,000"/></Field>}{commissionRequired && <Field label="درصد پورسانت" required><input dir="ltr" inputMode="decimal" value={percent} onChange={(event) => setPercent(normalizePercent(event.target.value))} placeholder="8 یا 1.5"/></Field>}<Field label="تاریخ شروع اجرا" required><PersianDateInput value={effectiveFrom} required onChange={setEffectiveFrom} ariaLabel="تاریخ شمسی شروع شرایط مالی"/></Field><Field label="دلیل تغییر" full required><textarea value={reason} onChange={(event) => setReason(event.target.value)} placeholder="مثلاً حکم جدید حقوق یا تغییر درصد پورسانت"/></Field></FormGrid>
    <div className="compensation-save-row"><button type="button" className="button button--primary" onClick={submit}><Plus size={17}/> ثبت نسخه جدید شرایط مالی</button><small>نسخه‌های قبلی حذف یا بازنویسی نمی‌شوند.</small></div>
    <section className="compensation-history"><div><span className="eyebrow">سابقه تغییرات</span><h4>تاریخچه حقوق و پورسانت</h4></div>{orderedSalesCompensationHistory(record).map((item, index) => <article key={item.id}><span className="compensation-history__index">{(index + 1).toLocaleString('en-US')}</span><div><strong>{salesCompensationModeLabel(item.mode)}</strong><p>{item.monthlyFixedSalaryRial ? `${formatPortalAmount(item.monthlyFixedSalaryRial)} ریال در ماه` : 'بدون حقوق ثابت'} · {item.commissionPercent ? `${item.commissionPercent}٪ پورسانت` : 'بدون پورسانت'}</p><small>شروع اجرا: {formatPersianDate(item.effectiveFrom)} · ثبت: {formatPersianDateTime(item.recordedAt)} · {item.actorName}</small><em>{item.reason}</em></div></article>)}{!record.salesCompensationHistory?.length && <div className="compact-empty">هنوز سابقه‌ای ثبت نشده است.</div>}</section>
  </div>;
}

function normalizePercent(value: string): string {
  const normalized = toLatinDigits(value).replace(/٫/g, '.').replace(/[^\d.]/g, '');
  const [whole, ...fraction] = normalized.split('.');
  return fraction.length ? `${whole}.${fraction.join('').slice(0, 2)}` : whole;
}

function employmentStatusLabel(status: PersonnelRecord['employmentStatus']): string {
  if (status === 'active') return 'فعال';
  if (status === 'ending_scheduled') return 'پایان زمان‌بندی‌شده';
  if (status === 'rehire_scheduled') return 'بازگشت زمان‌بندی‌شده';
  return 'خاتمه‌یافته';
}

function departureInitiatorLabel(value?: 'employee' | 'organization'): string {
  return value === 'employee' ? 'استعفا / درخواست پرسنل' : value === 'organization' ? 'قطع همکاری با تصمیم سازمان' : 'نوع ثبت نشده';
}

function lifecycleEventTitle(event: NonNullable<PersonnelRecord['lifecycleHistory']>[number]): string {
  if (event.kind === 'employment_started') return 'شروع همکاری';
  if (event.kind === 'employment_end_scheduled') return `${departureInitiatorLabel(event.departureInitiator)} — زمان‌بندی پایان`;
  if (event.kind === 'employment_ended') return departureInitiatorLabel(event.departureInitiator);
  if (event.kind === 'employment_end_cancelled') return 'لغو پایان همکاری زمان‌بندی‌شده';
  if (event.kind === 'rehire_scheduled') return 'بازگشت به همکاری زمان‌بندی‌شده';
  return 'بازگشت به همکاری';
}

function SalesHierarchyOverview({personnel, selected, onSelect}: {personnel: PersonnelRecord[]; selected: string; onSelect: (level: string) => void}) {
  return <section className="sales-hierarchy-panel"><div className="sales-hierarchy-heading"><span><Crown size={20}/></span><div><strong>سلسله‌مراتب شبکه فروش</strong><p>رده فروش همان سمت پرسنل است و شعبه محل استقرار، همان شعبه فروش او محسوب می‌شود.</p></div><button className={selected === 'all' ? 'active' : ''} onClick={() => onSelect('all')}>نمایش همه</button></div><div className="sales-hierarchy-flow">{SALES_LEVELS.map((level, index) => <button key={level.id} className={selected === level.id ? 'active' : ''} onClick={() => onSelect(selected === level.id ? 'all' : level.id)}><span>{index === SALES_LEVELS.length - 1 ? <Headphones size={18}/> : index === 0 ? <Crown size={18}/> : <UsersRound size={18}/>}</span><div><small>سطح {(index + 1).toLocaleString('en-US')}</small><strong>{level.label}</strong><b>{personnel.filter((item) => item.salesHierarchyLevel === level.id).length.toLocaleString('en-US')} نفر</b></div>{index < SALES_LEVELS.length - 1 && <i>←</i>}</button>)}</div></section>;
}

function PersonnelDialog({record, state, service, execute, initialTab, onClose, onSubmit, onCreateAccount, onAssignmentChange, onEndEmployment, onCancelEnd, onRehire, onAddCompensation}: {record?: PersonnelRecord; state: FoundationState; service: LocalFoundationService; execute: FoundationExecutor; initialTab: PersonnelTab; onClose: () => void; onSubmit: (input: PersonnelInput) => void; onCreateAccount: (record: PersonnelRecord) => void; onAssignmentChange: (record: PersonnelRecord, kind: PersonnelMovementKind) => void; onEndEmployment: (record: PersonnelRecord) => void; onCancelEnd: (record: PersonnelRecord) => void; onRehire: (record: PersonnelRecord) => void; onAddCompensation: (input: SalesCompensationInput) => Promise<unknown>}) {
  const mayManagePersonnel = can(state.activeUser, 'organization.personnel.manage'); const mayViewBank = can(state.activeUser, 'organization.personnel.banking.view'); const mayManageBank = can(state.activeUser, 'organization.personnel.banking.manage');
  const mayViewAssets = ['fixed-asset', 'asset-transfer', 'asset-maintenance'].every((moduleId) => can(state.activeUser, permissionFor(moduleId, 'view')));
  const mayViewDocuments = state.activeUser.permissions.includes(PERSONNEL_DOCUMENT_PERMISSION_READ) || state.activeUser.permissions.includes(PERSONNEL_DOCUMENT_PERMISSION_MANAGE);
  const [tab, setTab] = useState<PersonnelTab | null>(initialTab);
  const mayManage = mayManagePersonnel && tab !== 'documents';
  const [form, setForm] = useState<PersonnelInput>(() => record ? stripPersonnel(record) : emptyPersonnel(state));
  const [errors,setErrors]=useState<string[]>([]);
  const similarPersonnel = useMemo(() => {
    if (!form.firstName.trim() || !form.lastName.trim()) return [];
    const normalizedName = normalizePersonName(`${form.firstName} ${form.lastName}`);
    return state.personnel.filter((person) => person.id !== record?.id && normalizePersonName(`${person.firstName} ${person.lastName}`) === normalizedName);
  }, [form.firstName, form.lastName, record?.id, state.personnel]);
  const linkedUser = state.users.find((user) => user.id === record?.linkedUserId);
  const employmentTypeOptions = [...new Set([...EMPLOYMENT_TYPE_OPTIONS, form.employmentType].filter(Boolean))];
  const selectedUnitIsSales = state.units.find((item) => item.id === form.unitId)?.name.includes('فروش') ?? false;
  const availablePositions = positionsForUnit(state.positions, form.unitId, record?.positionId).filter((position) => position.status === 'active' || position.id === record?.positionId);
  const set = <K extends keyof PersonnelInput>(key: K, value: PersonnelInput[K]) => setForm((current) => key === 'positionId' && current.salesHierarchyLevel && selectedUnitIsSales ? current : {...current, [key]: value});
  const changeUnit = (nextUnitId: string) => setForm((current) => {
    const currentPosition = state.positions.find((position) => position.id === current.positionId);
    return {...current, unitId: nextUnitId, positionId: currentPosition && positionSupportsUnit(currentPosition, nextUnitId) ? current.positionId : ''};
  });
  const salesRelevant = selectedUnitIsSales || Boolean(form.salesHierarchyLevel);
  useEffect(() => {
    setForm((current) => {
      const positionId = selectedUnitIsSales ? positionIdForSalesHierarchy(current.salesHierarchyLevel) ?? current.positionId : current.positionId;
      const salesBranchUnitId = current.salesHierarchyLevel ? current.branchUnitId : undefined;
      const salesAssignmentStartDate = current.salesHierarchyLevel
        ? selectedUnitIsSales ? current.startDate : current.salesAssignmentStartDate || (record?.salesHierarchyLevel ? record.salesAssignmentStartDate || record.startDate : record ? todayIsoDate() : current.startDate)
        : undefined;
      return positionId === current.positionId && salesBranchUnitId === current.salesBranchUnitId && salesAssignmentStartDate === current.salesAssignmentStartDate ? current : {...current, positionId, salesBranchUnitId, salesAssignmentStartDate};
    });
  }, [form.salesHierarchyLevel, form.branchUnitId, form.startDate, record, selectedUnitIsSales]);
  const movementActions = new Set(['organization.personnel.branch_transferred', 'organization.personnel.sales_transferred', 'organization.personnel.unit_changed', 'organization.personnel.position_changed']);
  const chooseSalesStructure = (structureId: string) => {
    const structure = state.salesStructures.find((item) => item.id === structureId && item.status === 'active');
    setForm((current) => structure ? {...current, salesStructureId: structure.id, salesBranchUnitId: structure.branchUnitId, branchUnitId: structure.branchUnitId, salesSupervisorPersonnelId: structure.callCenterSupervisorPersonnelId, managerPersonnelId: structure.callCenterSupervisorPersonnelId, salesChannel: 'call_center'} : {...current, salesStructureId: undefined, salesSupervisorPersonnelId: undefined});
  };
  const history = state.audits.filter((item) => (item.metadata?.personnelId === record?.id || (linkedUser && item.effectiveUserId === linkedUser.id)) && !movementActions.has(item.action));
  const tabs: {id: PersonnelTab; label: string; description: string}[] = [{id: 'personal', label: 'اطلاعات فردی', description: 'مشخصات هویتی و اطلاعات پایه پرسنل'}, {id: 'contact', label: 'تماس و نشانی', description: 'شماره‌های تماس، ایمیل و نشانی محل سکونت'}, {id: 'employment', label: 'همکاری و جایگاه سازمانی', description: 'نوع همکاری، واحد، سمت، شعبه و ساختار فروش'}, ...(salesRelevant && mayManage ? [{id: 'compensation' as PersonnelTab, label: 'حقوق و پورسانت فروش', description: 'نوع پرداخت، مبلغ ثابت، درصد پورسانت و سابقه تاریخ‌دار'}] : []), ...(mayViewBank ? [{id: 'banking' as PersonnelTab, label: 'اطلاعات بانکی', description: 'حساب، کارت و شبای پرسنل'}] : []), {id: 'emergency', label: 'تماس اضطراری', description: 'فرد قابل تماس در شرایط ضروری'}, ...(record ? [{id: 'account' as PersonnelTab, label: 'حساب کاربری', description: 'حساب ورود، نقش و وضعیت دسترسی'}, ...(mayViewDocuments ? [{id: 'documents' as PersonnelTab, label: 'مدارک و تکمیل پرونده', description: 'مدارک اجباری، عکس و فایل‌های تکمیلی پرسنل'}] : []), ...(mayViewAssets ? [{id: 'assets' as PersonnelTab, label: 'دارایی‌ها و اموال', description: 'دارایی جاری، تحویل و عودت، سوابق و گزارش‌های خرابی'}] : []), {id: 'history' as PersonnelTab, label: 'تاریخچه پرونده', description: 'گردش تغییرات، انتقال‌ها و رویدادهای ثبت‌شده'}] : [])];
  return <Modal onClose={onClose} wide><Heading eyebrow="پرونده پرسنلی" title={record ? personnelDisplayLabel(record,state) : 'ایجاد پرسنل جدید'} text="اطلاعات شغلی و هویتی این بخش از حساب ورود به سامانه مستقل است." onClose={onClose} />{similarPersonnel.length>0&&<div className="notice notice--warning identity-safety-notice" role="status" aria-live="polite"><CircleAlert size={18}/><span><strong>نام مشابه در سازمان وجود دارد.</strong><span>فقط نام یکسان است؛ پیش از ثبت، کد پرسنلی، واحد و سمت را بررسی کنید. هیچ ادغامی خودکار انجام نمی‌شود.</span><small>موارد مشابه: {similarPersonnel.map((person) => personnelDisplayLabel(person,state)).join('؛ ')}</small></span></div>}<div className="personnel-accordion">{tabs.map((item, index) => <section key={item.id} className={`personnel-accordion__item ${tab === item.id ? 'personnel-accordion__item--open' : ''}`}><button type="button" className="personnel-accordion__trigger" aria-expanded={tab === item.id} aria-controls={`personnel-section-${item.id}`} onClick={() => setTab((current) => current === item.id ? null : item.id)}><span className="personnel-accordion__number">{(index + 1).toLocaleString('en-US')}</span><span className="personnel-accordion__title"><strong>{item.label}</strong><small>{item.description}</small></span><ChevronDown className="personnel-accordion__chevron" size={19}/></button>{tab === item.id && <div id={`personnel-section-${item.id}`} className="record-tab-body personnel-accordion__body">
    {tab === 'personal' && <FormGrid><Field label="کد پرسنلی" system><input value={form.personnelCode} readOnly aria-readonly="true" /><small>شماره نهایی هنگام ایجاد پرونده توسط سیستم تخصیص داده می‌شود.</small></Field><Field label="کد ملی" required><input aria-required="true" value={form.nationalId ?? ''} disabled={!mayManage} onChange={(e) => set('nationalId', e.target.value)} inputMode="numeric" maxLength={10} /></Field><Field label="نام" required><input aria-required="true" value={form.firstName} disabled={!mayManage} onChange={(e) => set('firstName', e.target.value)} /></Field><Field label="نام خانوادگی" required><input aria-required="true" value={form.lastName} disabled={!mayManage} onChange={(e) => set('lastName', e.target.value)} /></Field><Field label="نام پدر"><input value={form.fatherName ?? ''} disabled={!mayManage} onChange={(e) => set('fatherName', e.target.value)} /></Field><Field label="شماره شناسنامه"><input value={form.identityNumber ?? ''} disabled={!mayManage} onChange={(e) => set('identityNumber', e.target.value)} /></Field><Field label="تاریخ تولد"><PersianDateInput value={form.birthDate} disabled={!mayManage} onChange={(value) => set('birthDate', value || undefined)} ariaLabel="تاریخ تولد شمسی" /></Field><Field label="محل تولد"><input value={form.birthPlace ?? ''} disabled={!mayManage} onChange={(e) => set('birthPlace', e.target.value)} /></Field><Field label="جنسیت" required><select aria-required="true" value={form.gender} disabled={!mayManage} onChange={(e) => set('gender', e.target.value as PersonnelInput['gender'])}><option value="unspecified">انتخاب کنید</option><option value="female">زن</option><option value="male">مرد</option></select></Field><Field label="وضعیت تأهل"><select value={form.maritalStatus} disabled={!mayManage} onChange={(e) => set('maritalStatus', e.target.value as PersonnelInput['maritalStatus'])}><option value="unspecified">ثبت نشده</option><option value="single">مجرد</option><option value="married">متأهل</option></select></Field></FormGrid>}
    {tab === 'contact' && <FormGrid><Field label="همراه اصلی" required><input aria-required="true" value={form.primaryMobile} disabled={!mayManage} onChange={(e) => set('primaryMobile', normalizeIranianMobile(e.target.value))} inputMode="tel" dir="ltr" maxLength={11} placeholder="09125026707" /></Field><Field label="شماره تماس دوم" required><input aria-required="true" value={form.secondaryMobile ?? ''} disabled={!mayManage} onChange={(e) => set('secondaryMobile', normalizeIranianMobile(e.target.value))} inputMode="tel" dir="ltr" maxLength={11} placeholder="09121234567" /></Field><Field label="تلفن ثابت با پیش‌شماره"><input value={form.phone ?? ''} disabled={!mayManage} onChange={(e) => set('phone', normalizeIranianLandline(e.target.value))} inputMode="tel" dir="ltr" maxLength={11} placeholder="02156174680" /></Field><Field label="ایمیل شخصی"><input type="email" value={form.personalEmail ?? ''} disabled={!mayManage} onChange={(e) => set('personalEmail', e.target.value)} /></Field><Field label="استان" required><input aria-required="true" value={form.province ?? ''} disabled={!mayManage} onChange={(e) => set('province', e.target.value)} /></Field><Field label="شهر" required><input aria-required="true" value={form.city ?? ''} disabled={!mayManage} onChange={(e) => set('city', e.target.value)} /></Field><Field label="کد پستی"><input inputMode="numeric" dir="ltr" maxLength={10} value={form.postalCode ?? ''} disabled={!mayManage} onChange={(e) => set('postalCode', digitsOnly(e.target.value, 10))} /></Field><Field label="نشانی" full required><textarea aria-required="true" value={form.address ?? ''} disabled={!mayManage} onChange={(e) => set('address', e.target.value)} /></Field></FormGrid>}
    {tab === 'employment' && <><FormGrid><Field label="وضعیت همکاری" system><input value={employmentStatusLabel(form.employmentStatus)} readOnly aria-readonly="true" /></Field><Field label="نوع همکاری" required><select aria-required="true" value={form.employmentType} disabled={!mayManage} onChange={(e) => set('employmentType', e.target.value)}>{employmentTypeOptions.map((type) => <option key={type} value={type}>{type}</option>)}</select></Field><Field label="تاریخ شروع" required><PersianDateInput value={form.startDate} disabled={!mayManage} required onChange={(value) => set('startDate', value)} ariaLabel="تاریخ شروع همکاری شمسی" /></Field><Field label="تاریخ پایان" system><PersianDateInput value={form.endDate} disabled onChange={() => undefined} ariaLabel="تاریخ پایان همکاری شمسی" /></Field>{!record && <><Field label="واحد سازمانی" required><select aria-required="true" value={form.unitId} disabled={!mayManage} onChange={(e) => changeUnit(e.target.value)}><option value="">انتخاب کنید</option>{state.units.filter((item) => item.status === 'active' && item.type !== 'شعبه').map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="سمت سازمانی" required><select aria-required="true" value={form.positionId} disabled={!mayManage || !form.unitId} onChange={(e) => set('positionId', e.target.value)}><option value="">{form.unitId ? 'انتخاب سمت مجاز این واحد' : 'ابتدا واحد را انتخاب کنید'}</option>{availablePositions.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></Field><Field label="شعبه محل استقرار"><select value={form.branchUnitId ?? ''} disabled={!mayManage} onChange={(e) => set('branchUnitId', e.target.value || undefined)}><option value="">تعیین نشده</option>{state.units.filter((item) => item.status === 'active' && item.type === 'شعبه').map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field></>}<Field label="مدیر مستقیم"><select value={form.managerPersonnelId ?? ''} disabled={!mayManage} onChange={(e) => set('managerPersonnelId', e.target.value || undefined)}><option value="">تعیین نشده</option>{state.personnel.filter((item) => item.id !== record?.id && item.employmentStatus === 'active').map((item) => <option key={item.id} value={item.id}>{personnelDisplayLabel(item,state)}</option>)}</select></Field></FormGrid>{record && mayManage && <PersonnelLifecycleInlineActions personnel={record} onEnd={() => onEndEmployment(record)} onCancelEnd={() => onCancelEnd(record)} onRehire={() => onRehire(record)}/>}<section className={`sales-assignment-form ${salesRelevant ? 'sales-assignment-form--active' : ''}`}><div className="sales-assignment-form__heading"><span><Crown size={19}/></span><div><strong>جایگاه در شبکه فروش</strong><small>این اطلاعات از واحد و سمت سازمانی جداست و مبنای انتساب فروش، سرپرست و شعبه فروش خواهد بود.</small></div></div><FormGrid><Field label="رده در سلسله‌مراتب فروش" required={selectedUnitIsSales}><select aria-required={selectedUnitIsSales} value={form.salesHierarchyLevel ?? ''} disabled={!mayManage} onChange={(e) => {const value = e.target.value as SalesHierarchyLevel | ''; set('salesHierarchyLevel', value || undefined); if (!value) {set('salesChannel', undefined);set('salesSupervisorPersonnelId', undefined);set('salesBranchUnitId', undefined);}}}><option value="">عضو شبکه فروش نیست</option>{SALES_LEVELS.map((level) => <option key={level.id} value={level.id}>{level.label}</option>)}</select></Field>{salesRelevant && <><Field label="کانال فروش" required={form.salesHierarchyLevel === 'seller'}><select aria-required={form.salesHierarchyLevel === 'seller'} value={form.salesChannel ?? ''} disabled={!mayManage} onChange={(e) => set('salesChannel', (e.target.value || undefined) as SalesChannel | undefined)}><option value="">تعیین نشده</option>{SALES_CHANNELS.map((channel) => <option key={channel.id} value={channel.id}>{channel.label}</option>)}</select></Field><Field label="سرپرست مستقیم فروش"><select value={form.salesSupervisorPersonnelId ?? ''} disabled={!mayManage} onChange={(e) => set('salesSupervisorPersonnelId', e.target.value || undefined)}><option value="">بالاترین رده / تعیین نشده</option>{state.personnel.filter((item) => item.id !== record?.id && item.employmentStatus === 'active' && item.salesHierarchyLevel).map((item) => <option key={item.id} value={item.id}>{personnelDisplayLabel(item,state)} — {salesLevelLabel(item.salesHierarchyLevel)}</option>)}</select></Field><Field label="شعبه منتسب به فروش" required={['seller','sales_supervisor','senior_supervisor'].includes(form.salesHierarchyLevel ?? '')}><select aria-required={['seller','sales_supervisor','senior_supervisor'].includes(form.salesHierarchyLevel ?? '')} value={form.salesBranchUnitId ?? ''} disabled={!mayManage} onChange={(e) => set('salesBranchUnitId', e.target.value || undefined)}><option value="">سراسری / تعیین نشده</option>{state.units.filter((item) => item.status === 'active' && item.type === 'شعبه').map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field></>}</FormGrid></section>{record && <AssignmentSummary record={record} state={state} mayManage={mayManage} onChange={(kind) => onAssignmentChange(record, kind)} />}</>}
    {tab === 'employment' && form.salesHierarchyLevel && <section className="sales-role-date-panel"><div className="compensation-policy-note"><CircleAlert size={18}/><span>{selectedUnitIsSales ? 'چون همکاری اولیه این پرسنل در واحد فروش است، تاریخ شروع نقش فروش با تاریخ شروع همکاری یکسان نگه داشته می‌شود.' : 'این پرسنل در کنار جایگاه سازمانی اصلی، نقش فروش هم دارد؛ تاریخ واقعی شروع نقش فروش را مستقل انتخاب کنید.'}</span></div><FormGrid><Field label="تاریخ شروع نقش فروش" full required><PersianDateInput value={form.salesAssignmentStartDate} disabled={!mayManage || selectedUnitIsSales} required onChange={(value) => set('salesAssignmentStartDate', value)} ariaLabel="تاریخ شمسی شروع نقش فروش" /></Field></FormGrid></section>}
    {tab === 'employment' && record && isSalesManagementLevel(record.salesHierarchyLevel) && <SalesManagementOwnershipPanel personnel={record} state={state}/>}
    {tab === 'employment' && form.salesHierarchyLevel === 'seller' && <SellerStructurePicker record={record} state={state} form={form} mayManage={mayManage} onSelect={chooseSalesStructure} />}
    {tab === 'compensation' && salesRelevant && mayManage && (record ? <SalesCompensationEditor record={record} onSubmit={onAddCompensation}/> : <SalesCompensationInitialPreview level={form.salesHierarchyLevel}/>)}
    {tab === 'banking' && mayViewBank && <><div className="sensitive-note"><ShieldAlert size={20} /><span><strong>اطلاعات حساس</strong> مقدارهای بانکی در Audit ذخیره نمی‌شوند؛ فقط وقوع تغییر ثبت می‌شود.</span></div><FormGrid><Field label="نام بانک" required><input aria-required="true" value={form.bankName ?? ''} disabled={!mayManageBank} onChange={(e) => set('bankName', e.target.value)} /></Field><Field label="شماره حساب"><input value={form.accountNumber ?? ''} disabled={!mayManageBank} onChange={(e) => set('accountNumber', digitsOnly(e.target.value))} inputMode="numeric" dir="ltr" /></Field><Field label="شماره کارت" required><input aria-required="true" value={form.cardNumber ?? ''} disabled={!mayManageBank} onChange={(e) => set('cardNumber', normalizeBankCard(e.target.value))} inputMode="numeric" dir="ltr" maxLength={16} placeholder="6104337812345678" /></Field><Field label="شماره شبا"><input value={form.iban ?? ''} disabled={!mayManageBank} onChange={(e) => set('iban', normalizeIranianIban(e.target.value))} inputMode="numeric" dir="ltr" maxLength={26} placeholder="IR820540102680020817909002" /></Field></FormGrid></>}
    {tab === 'emergency' && <FormGrid><Field label="نام فرد تماس"><input value={form.emergencyName ?? ''} disabled={!mayManage} onChange={(e) => set('emergencyName', e.target.value)} /></Field><Field label="نسبت"><input value={form.emergencyRelation ?? ''} disabled={!mayManage} onChange={(e) => set('emergencyRelation', e.target.value)} /></Field><Field label="شماره تماس"><input value={form.emergencyPhone ?? ''} disabled={!mayManage} onChange={(e) => set('emergencyPhone', digitsOnly(e.target.value, 11))} inputMode="tel" dir="ltr" maxLength={11} /></Field></FormGrid>}
    {tab === 'account' && record && <div className="linked-account-panel">{linkedUser ? <><span className="record-avatar"><KeyRound size={22} /></span><div><strong>{linkedUser.username}</strong><p>{linkedUser.roles.join('، ')} · <i className={`status-badge status-badge--${linkedUser.status}`}>{linkedUser.status === 'active' ? 'فعال' : 'غیرفعال'}</i></p><small>حساب فقط برای ورود و دسترسی است و اطلاعات هویتی را تکرار نمی‌کند.</small></div></> : <><span className="record-avatar"><UserPlus size={22} /></span><div><strong>این پرسنل حساب کاربری ندارد</strong><p>وجود پرونده پرسنلی برای ایجاد حساب ورود کافی است.</p>{record.employmentStatus === 'active' && can(state.activeUser, 'organization.personnel.account.manage') && <button className="button button--primary" onClick={() => onCreateAccount(record)}>ایجاد حساب کاربری</button>}</div></>}</div>}
    {tab === 'documents' && record && mayViewDocuments && <PersonnelDocumentsSection state={state} service={service} execute={execute} personnelId={record.id} mode="hr"/>}
    {tab === 'assets' && record && <MyAssetsSection state={state} service={service} execute={execute} personnelId={record.id} readOnly viewMode="personnel-profile"/>}
    {tab === 'history' && <div className="record-history">{[...(record?.lifecycleHistory ?? [])].reverse().map((item) => <article className="movement-history-item" key={item.id}><span /><div><strong>{lifecycleEventTitle(item)}</strong><p>تاریخ مؤثر: {formatPersianDate(item.effectiveDate)} · {item.reason}</p><small>{item.actorName} · ثبت در {formatPersianDateTime(item.recordedAt)}{item.handoffNotes ? ` · تحویل کار: ${item.handoffNotes}` : ''}</small></div></article>)}{[...(record?.movements ?? [])].reverse().map((item) => <article className="movement-history-item" key={item.id}><span /><div><strong>{movementTitle(item.kind)}</strong><p>{movementDescription(item, state)}</p><small>{item.actorName} · ثبت در {formatPersianDateTime(item.recordedAt)} · دلیل: {item.reason}</small></div></article>)}{history.map((item) => <article key={item.id}><span /><div><strong>{item.summary}</strong><small>{item.actorName} · {formatPersianDateTime(item.occurredAt)}</small></div></article>)}{!history.length && !record?.movements?.length && !record?.lifecycleHistory?.length && <p>هنوز رویدادی برای این پرونده ثبت نشده است.</p>}</div>}
  </div>}</section>)}</div><FormValidationSummary errors={errors}/>{mayManage && tab !== 'account' && tab !== 'assets' && tab !== 'history' && <div className="dialog-actions personnel-accordion__actions"><button className="button button--secondary" onClick={onClose}>انصراف</button><button className="button button--primary" onClick={() => {const next=validateRequired([{label:'کد ملی',value:form.nationalId,valid:(value)=>String(value??'').replace(/[۰-۹]/g,(digit)=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit))).replace(/\D/g,'').length===10,message:'فیلد «کد ملی» الزامی است و باید ۱۰ رقم باشد.'},{label:'نام',value:form.firstName},{label:'نام خانوادگی',value:form.lastName},{label:'جنسیت',value:form.gender,valid:(value)=>value!=='unspecified',message:'فیلد «جنسیت» الزامی است.'},{label:'همراه اصلی',value:form.primaryMobile,valid:(value)=>/^09\d{9}$/.test(String(value??'')),message:'فیلد «همراه اصلی» باید ۱۱ رقم و با 09 شروع شود.'},{label:'شماره تماس دوم',value:form.secondaryMobile,valid:(value)=>/^09\d{9}$/.test(String(value??'').replace(/[۰-۹]/g,(digit)=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit))).replace(/\D/g,'')),message:'فیلد «شماره تماس دوم» الزامی است و باید معتبر باشد.'},{label:'استان',value:form.province},{label:'شهر',value:form.city},{label:'نشانی',value:form.address},{label:'کد پستی',value:form.postalCode,valid:(value)=>!String(value??'').trim()||isValidPostalCode(String(value)),message:'فیلد «کد پستی» در صورت ورود باید دقیقاً ۱۰ رقم باشد.'},{label:'نام بانک',value:form.bankName},{label:'شماره کارت',value:form.cardNumber,valid:(value)=>String(value??'').replace(/[۰-۹]/g,(digit)=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit))).replace(/\D/g,'').length===16,message:'فیلد «شماره کارت» الزامی است و باید ۱۶ رقم باشد.'},{label:'شماره شبا',value:form.iban,valid:(value)=>!String(value??'').trim()||isValidIranianIban(String(value)),message:'فیلد «شماره شبا» باید شامل IR و ۲۴ رقم باشد.'},{label:'نوع همکاری',value:form.employmentType},{label:'تاریخ شروع',value:form.startDate},{label:'واحد سازمانی',value:form.unitId},{label:'سمت',value:form.positionId},...(form.employmentStatus==='ended'?[{label:'تاریخ پایان',value:form.endDate}]:[]),...(selectedUnitIsSales?[{label:'رده در سلسله‌مراتب فروش',value:form.salesHierarchyLevel}]:[]),...(form.salesHierarchyLevel==='seller'?[{label:'کانال فروش',value:form.salesChannel},{label:'کال‌سنتر فعال',value:form.salesStructureId}]:[]),...(['seller','sales_supervisor','senior_supervisor'].includes(form.salesHierarchyLevel ?? '')?[{label:'شعبه منتسب به فروش',value:form.salesBranchUnitId}]:[])]);setErrors(next);if(next.length){setTab(!form.nationalId?.trim()||!form.firstName.trim()||!form.lastName.trim()||form.gender==='unspecified'?'personal':!form.primaryMobile.trim()||!form.secondaryMobile?.trim()||!form.province?.trim()||!form.city?.trim()||!form.address?.trim()?'contact':!form.bankName?.trim()||!form.cardNumber?.trim()?'banking':'employment');return;}onSubmit(form);}}>{record ? 'ذخیره تغییرات' : 'ایجاد پرونده'}</button></div>}</Modal>;
}

function SalesBranchScopeCell({personnel, state}: {personnel: PersonnelRecord; state: FoundationState}) {
  const names = salesBranchNamesForPersonnel(personnel, state);
  const managed = isSalesManagementLevel(personnel.salesHierarchyLevel);
  const paths = managed ? activeSalesStructuresForPersonnel(state, personnel.id, personnel.salesHierarchyLevel).length : 0;
  return <div className={`sales-branch-scope-cell ${managed ? 'sales-branch-scope-cell--managed' : ''}`}>
    <div>{names.length ? names.map((name) => <i key={name}>{name}</i>) : <small>تعیین نشده</small>}</div>
    {managed && <small>{names.length.toLocaleString('en-US')} شعبه · {paths.toLocaleString('en-US')} مسیر فعال</small>}
  </div>;
}

function SalesManagementOwnershipPanel({personnel, state}: {personnel: PersonnelRecord; state: FoundationState}) {
  const paths = activeSalesStructuresForPersonnel(state, personnel.id, personnel.salesHierarchyLevel);
  const branchIds = managedSalesBranchIdsForPersonnel(state, personnel);
  const subordinateLabel = personnel.salesHierarchyLevel === 'sales_vice' ? 'مدیران فروش' : personnel.salesHierarchyLevel === 'sales_manager' ? 'سرپرستان ارشد' : 'سرپرستان کال‌سنتر';
  const subordinateId = (path: (typeof paths)[number]) => personnel.salesHierarchyLevel === 'sales_vice' ? path.salesManagerPersonnelId : personnel.salesHierarchyLevel === 'sales_manager' ? path.seniorSupervisorPersonnelId : path.callCenterSupervisorPersonnelId;
  return <section className="sales-management-ownership">
    <div className="sales-management-ownership__heading"><span><Building2 size={19}/></span><div><strong>شعبه‌های تحت مدیریت</strong><small>این حوزه از مسیرهای فعال ساختار فروش محاسبه می‌شود و با غیرفعال‌شدن مسیر به‌روز خواهد شد.</small></div><b>{branchIds.length.toLocaleString('en-US')} شعبه</b></div>
    {branchIds.length ? <div className="sales-management-ownership__grid">{branchIds.map((branchId) => {
      const branchPaths = paths.filter((path) => path.branchUnitId === branchId);
      const subordinateNames = [...new Set(branchPaths.map((path) => personnelName(state, subordinateId(path))).filter(Boolean))];
      return <article key={branchId}><span className="sales-management-ownership__icon"><MapPin size={17}/></span><div><strong>{state.units.find((unit) => unit.id === branchId)?.name ?? 'شعبه نامشخص'}</strong><small>{branchPaths.length.toLocaleString('en-US')} مسیر فعال</small><p>{subordinateLabel}: {subordinateNames.join('، ') || 'تعیین نشده'}</p></div></article>;
    })}</div> : <div className="sales-management-ownership__empty"><CircleAlert size={18}/><span>هنوز هیچ مسیر فروش فعالی برای این جایگاه ثبت نشده است.</span></div>}
    <p className="sales-management-ownership__policy">تغییر این فهرست از صفحه «سازمان ← ساختار فروش» انجام می‌شود تا سابقه مسیرها و انتساب پرسنل حفظ شود.</p>
  </section>;
}

function SellerStructurePicker({record, state, form, mayManage, onSelect}: {record?: PersonnelRecord; state: FoundationState; form: PersonnelInput; mayManage: boolean; onSelect: (structureId: string) => void}) {
  const activeStructures = state.salesStructures.filter((item) => item.status === 'active' && item.branchUnitId === form.branchUnitId && state.units.some((unit) => unit.id === item.branchUnitId && unit.status === 'active'));
  const selected = state.salesStructures.find((item) => item.id === form.salesStructureId);
  const branchName = state.units.find((item) => item.id === form.branchUnitId)?.name;
  return <section className="seller-structure-picker"><div className="seller-structure-picker__heading"><Headphones size={20}/><div><strong>اتصال فروشنده به سرپرست کال‌سنتر</strong><span>سرپرستان دارای مسیر فعال در شعبه محل استقرار نمایش داده می‌شوند.</span></div></div>{selected?.status === 'inactive' && <div className="notice notice--danger"><CircleAlert size={18}/><span>ساختار فعلی غیرفعال است و دیگر در فهرست انتخاب نمایش داده نمی‌شود. انتقال فروشنده را ثبت کنید.</span></div>}<FormGrid><Field label="سرپرست کال‌سنتر فعال" full required><select aria-required="true" value={selected?.status === 'active' && selected.branchUnitId === form.branchUnitId ? selected.id : ''} disabled={!mayManage || Boolean(record) || !form.branchUnitId} onChange={(event) => onSelect(event.target.value)}><option value="">{form.branchUnitId ? 'انتخاب سرپرست کال‌سنتر' : 'ابتدا شعبه محل استقرار را انتخاب کنید'}</option>{activeStructures.map((item) => <option key={item.id} value={item.id}>{salesStructureSupervisorName(item, state.personnel)}</option>)}</select></Field></FormGrid>{selected && <div className="seller-chain-preview"><span><small>شعبه محل استقرار و فروش</small><strong>{branchName ?? 'نامشخص'}</strong></span><span><small>سرپرست کال‌سنتر</small><strong>{salesStructureSupervisorName(selected, state.personnel)}</strong></span><span><small>سرپرست ارشد</small><strong>{personnelName(state, selected.seniorSupervisorPersonnelId)}</strong></span><span><small>مدیر فروش</small><strong>{personnelName(state, selected.salesManagerPersonnelId)}</strong></span><span><small>معاونت فروش</small><strong>{personnelName(state, selected.salesVicePersonnelId) || 'تعیین نشده'}</strong></span></div>}{record && <p className="seller-structure-picker__locked">برای حفظ تاریخچه، شعبه و سرپرست کال‌سنتر فروشنده موجود از این فرم ویرایش نمی‌شود؛ از دکمه «انتقال فروشنده» در پایین پرونده استفاده کنید.</p>}</section>;
}

function AssignmentSummary({record, state, mayManage, onChange}: {record: PersonnelRecord; state: FoundationState; mayManage: boolean; onChange: (kind: PersonnelMovementKind) => void}) {
  const salesMember = Boolean(record.salesHierarchyLevel);
  const primaryUnitIsSales = Boolean(state.units.find((item) => item.id === record.unitId)?.name.includes('فروش'));
  const items: {key: string; kind: PersonnelMovementKind; icon: ReactNode; label: string; value: string; action: string; changeable?: boolean}[] = [
    {key: 'unit', kind: 'unit_change', icon: <Building2 size={18} />, label: 'واحد سازمانی فعلی', value: state.units.find((item) => item.id === record.unitId && item.type !== 'شعبه')?.name ?? 'تعیین نشده', action: 'ثبت تغییر واحد'},
    {key: 'position', kind: 'position_change', icon: <BriefcaseBusiness size={18} />, label: primaryUnitIsSales ? 'سمت / رده فروش' : 'سمت سازمانی فعلی', value: primaryUnitIsSales ? salesLevelLabel(record.salesHierarchyLevel) : state.positions.find((item) => item.id === record.positionId)?.title ?? 'تعیین نشده', action: 'ثبت تغییر سمت', changeable: !primaryUnitIsSales},
    ...(salesMember && !primaryUnitIsSales ? [{key: 'secondary-sales-role', kind: 'position_change' as const, icon: <Crown size={18} />, label: 'نقش دوم در شبکه فروش', value: `${salesLevelLabel(record.salesHierarchyLevel)} · از ${formatDate(record.salesAssignmentStartDate)}`, action: '', changeable: false}] : []),
    ...(record.salesHierarchyLevel !== 'seller' ? [{key: 'branch', kind: 'branch_transfer' as const, icon: <MapPin size={18} />, label: salesMember ? 'شعبه محل استقرار و فروش' : 'شعبه محل استقرار', value: state.units.find((item) => item.id === record.branchUnitId && item.type === 'شعبه')?.name ?? 'تعیین نشده', action: record.branchUnitId ? 'ثبت انتقال شعبه' : 'ثبت استقرار شعبه'}] : []),
    ...(record.salesHierarchyLevel === 'seller' ? [{key: 'sales-path', kind: 'sales_transfer' as const, icon: <Headphones size={18}/>, label: 'سرپرست کال‌سنتر و مسیر فروش', value: salesStructureLabel(state, record.salesStructureId), action: 'انتقال فروشنده'}] : []),
  ];
  return <section className="assignment-summary"><div className="assignment-summary__heading"><div><strong>جایگاه و استقرار جاری</strong><span>{salesMember && !primaryUnitIsSales ? 'سمت سازمانی اصلی و نقش دوم فروش مستقل ثبت شده‌اند.' : 'برای عضو شبکه فروش، رده همان سمت و شعبه استقرار همان شعبه فروش است.'}</span></div><ArrowLeftRight size={20} /></div><div className="assignment-summary__grid">{items.map((item) => <article key={item.key}><span className="assignment-summary__icon">{item.icon}</span><div><small>{item.label}</small><strong>{item.value}</strong></div>{mayManage && record.employmentStatus === 'active' && item.changeable !== false && <button type="button" onClick={() => onChange(item.kind)}>{item.action}</button>}</article>)}</div></section>;
}

function AssignmentChangeDialog({personnel, kind, state, onClose, onSubmit}: {personnel: PersonnelRecord; kind: PersonnelMovementKind; state: FoundationState; onClose: () => void; onSubmit: (input: PersonnelAssignmentChangeInput) => void}) {
  const today = todayIsoDate();
  const [targetId, setTargetId] = useState(''); const [targetPositionId, setTargetPositionId] = useState(''); const [effectiveDate, setEffectiveDate] = useState(today); const [previousEndDate, setPreviousEndDate] = useState(today); const [newStartDate, setNewStartDate] = useState(today); const [reason, setReason] = useState(''); const [errors, setErrors] = useState<string[]>([]);
  const sales = kind === 'sales_transfer'; const branch = kind === 'branch_transfer'; const datedTransfer = branch || sales; const hasCurrentBranch = datedTransfer && Boolean(sales ? personnel.salesStructureId : personnel.branchUnitId); const title = sales ? 'انتقال فروشنده' : branch ? (hasCurrentBranch ? 'انتقال شعبه' : 'ثبت استقرار شعبه') : kind === 'unit_change' ? 'تغییر واحد سازمانی' : 'تغییر سمت سازمانی';
  const currentId = kind === 'unit_change' ? personnel.unitId : kind === 'position_change' ? personnel.positionId : sales ? personnel.salesStructureId : personnel.branchUnitId;
  const current = assignmentValue(kind, currentId, state);
  const options = sales ? state.salesStructures.filter((item) => item.status === 'active' && item.id !== currentId && state.units.some((unit) => unit.id === item.branchUnitId && unit.status === 'active')).map((item) => ({id: item.id, name: salesStructureLabel(state, item.id)})) : kind === 'position_change' ? positionsForUnit(state.positions, personnel.unitId).filter((item) => item.status === 'active' && item.id !== currentId).map((item) => ({id: item.id, name: item.title})) : state.units.filter((item) => item.status === 'active' && (kind === 'branch_transfer' ? item.type === 'شعبه' : item.type !== 'شعبه') && item.id !== currentId).map((item) => ({id: item.id, name: item.name}));
  const unitChangePositions = kind === 'unit_change' ? positionsForUnit(state.positions, targetId).filter((item) => item.status === 'active') : [];
  const destinationLabel = sales ? 'سرپرست کال‌سنتر مقصد' : branch ? 'شعبه مقصد' : kind === 'unit_change' ? 'واحد سازمانی جدید' : 'سمت سازمانی جدید';
  const submit = () => {const next = validateRequired([{label: destinationLabel, value: targetId}, ...(kind === 'unit_change' ? [{label: 'سمت سازمانی در واحد جدید', value: targetPositionId}] : []), ...(datedTransfer ? [...(hasCurrentBranch ? [{label: 'تاریخ پایان انتساب قبلی', value: previousEndDate}] : []), {label: 'تاریخ شروع انتساب جدید', value: newStartDate}] : [{label: 'تاریخ اجرای تغییر', value: effectiveDate}]), {label: 'دلیل تغییر', value: reason, valid: (value) => String(value).trim().length >= 3, message: 'فیلد «دلیل تغییر» الزامی است و باید توضیح قابل فهمی داشته باشد.'}]); if (hasCurrentBranch && previousEndDate && newStartDate && newStartDate < previousEndDate) next.push('تاریخ شروع انتساب جدید نمی‌تواند قبل از تاریخ پایان انتساب قبلی باشد.'); setErrors(next); if (!next.length) onSubmit({kind, targetId, targetPositionId: kind === 'unit_change' ? targetPositionId : undefined, effectiveDate: datedTransfer ? newStartDate : effectiveDate, previousEndDate: hasCurrentBranch ? previousEndDate : undefined, newStartDate: datedTransfer ? newStartDate : undefined, reason});};
  return <Modal onClose={onClose}><Heading eyebrow="گردش تغییر جایگاه" title={title} text={`برای ${personnelDisplayLabel(personnel,state)}؛ مقدار فعلی: ${current}`} onClose={onClose} /><div className="movement-notice"><ArrowLeftRight size={20} /><span><strong>ثبت غیرقابل حذف در پرونده</strong>{datedTransfer ? 'انتصاب قبلی با تاریخ پایان بسته می‌شود و انتصاب جدید با تاریخ شروع جداگانه ثبت خواهد شد.' : 'مقدار قبلی، مقدار جدید، تاریخ اجرا، دلیل و ثبت‌کننده نگهداری می‌شوند.'}</span></div><FormGrid><FormValidationSummary errors={errors}/><Field label={destinationLabel} full required><select aria-required="true" value={targetId} onChange={(event) => {setTargetId(event.target.value);setTargetPositionId('');}}><option value="">انتخاب کنید</option>{options.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field>{kind === 'unit_change' && <Field label="سمت سازمانی در واحد جدید" full required><select aria-required="true" value={targetPositionId} disabled={!targetId} onChange={(event)=>setTargetPositionId(event.target.value)}><option value="">{targetId?'انتخاب سمت مجاز واحد جدید':'ابتدا واحد جدید را انتخاب کنید'}</option>{unitChangePositions.map((item)=><option key={item.id} value={item.id}>{item.title}</option>)}</select></Field>}{datedTransfer ? <>{hasCurrentBranch && <Field label="تاریخ پایان انتساب قبلی" required><PersianDateInput value={previousEndDate} required onChange={setPreviousEndDate} ariaLabel="تاریخ شمسی پایان انتساب قبلی" /></Field>}<Field label="تاریخ شروع انتساب جدید" full={!hasCurrentBranch} required><PersianDateInput value={newStartDate} required onChange={setNewStartDate} ariaLabel="تاریخ شمسی شروع انتساب جدید" /></Field></> : <Field label="تاریخ اجرای تغییر" full required><PersianDateInput value={effectiveDate} required onChange={setEffectiveDate} ariaLabel="تاریخ شمسی اجرای تغییر" /></Field>}<Field label="دلیل تغییر" full required><textarea aria-required="true" value={reason} onChange={(event) => setReason(event.target.value)} placeholder="علت تغییر، شماره حکم یا توضیح لازم را ثبت کنید…" /></Field></FormGrid><div className="dialog-actions"><button className="button button--secondary" onClick={onClose}>انصراف</button><button className="button button--primary" onClick={submit}>ثبت {title}</button></div></Modal>;
}

function movementTitle(kind: PersonnelMovementKind) {return kind === 'sales_transfer' ? 'انتقال فروشنده' : kind === 'branch_transfer' ? 'انتقال شعبه' : kind === 'unit_change' ? 'تغییر واحد سازمانی' : 'تغییر سمت سازمانی';}
function assignmentValue(kind: PersonnelMovementKind, id: string | undefined, state: FoundationState) {if (!id) return 'تعیین نشده'; if (kind === 'sales_transfer') return salesStructureLabel(state, id); return kind === 'position_change' ? state.positions.find((item) => item.id === id)?.title ?? 'نامشخص' : state.units.find((item) => item.id === id)?.name ?? 'نامشخص';}
function movementDescription(item: PersonnelMovement, state: FoundationState) {const from = assignmentValue(item.kind, item.fromId, state); const to = assignmentValue(item.kind, item.toId, state); return ['branch_transfer','sales_transfer'].includes(item.kind) ? (item.fromId ? `پایان انتساب به «${from}» در ${formatDate(item.previousEndedAt)} و شروع انتساب به «${to}» از ${formatDate(item.newStartedAt)}` : `شروع نخستین انتساب به «${to}» از ${formatDate(item.newStartedAt)}`) : `از «${from}» به «${to}» با تاریخ اجرا ${formatDate(item.effectiveDate)}`;}
function formatDate(value?: string) {return formatPersianDate(value);}

function AccountDialog({person, state, onClose, onSubmit}: {person: PersonnelRecord; state: FoundationState; onClose: () => void; onSubmit: (input: {username: string; password: string; roleIds: string[]; status: UserStatus}) => void}) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [roleIds, setRoleIds] = useState<string[]>([]);
  const [roleQuery, setRoleQuery] = useState('');
  const [status, setStatus] = useState<UserStatus>('active');
  const [errors, setErrors] = useState<string[]>([]);
  const activeRoles = useMemo(() => state.roles.filter((role) => role.status === 'active'), [state.roles]);
  const visibleRoles = useMemo(() => {
    const query = roleQuery.trim().toLocaleLowerCase('fa-IR');
    return activeRoles.filter((role) => !query || `${role.name} ${role.description}`.toLocaleLowerCase('fa-IR').includes(query));
  }, [activeRoles, roleQuery]);
  const selectedRoles = activeRoles.filter((role) => roleIds.includes(role.id));
  const toggleRole = (roleId: string, checked: boolean) => setRoleIds((current) => checked ? [...current, roleId] : current.filter((id) => id !== roleId));
  const submit = () => {
    const next = validateRequired([
      {label: 'نام کاربری', value: username, valid: (value) => String(value).trim().length >= 3, message: 'فیلد «نام کاربری» الزامی است و باید حداقل ۳ نویسه داشته باشد.'},
      {label: 'رمز عبور اولیه', value: password, valid: (value) => String(value).length >= 8, message: 'فیلد «رمز عبور اولیه» الزامی است و باید حداقل ۸ نویسه داشته باشد.'},
      {label: 'نقش‌های دسترسی', value: roleIds},
    ]);
    setErrors(next);
    if (!next.length) onSubmit({username, password, roleIds, status});
  };

  return <Modal onClose={onClose}>
    <Heading eyebrow="حساب کاربری" title={`ایجاد حساب برای ${personnelDisplayLabel(person,state)}`} text="اطلاعات فردی از پرونده پرسنلی خوانده می‌شود و در حساب تکرار نخواهد شد." onClose={onClose} />
    <FormGrid>
      <FormValidationSummary errors={errors}/>
      <Field label="نام کاربری" full required><input aria-required="true" value={username} dir="ltr" onChange={(event) => setUsername(event.target.value)} placeholder="firstname.lastname" /></Field>
      <Field label="رمز عبور اولیه" required><input aria-required="true" type="password" value={password} dir="ltr" onChange={(event) => setPassword(event.target.value)} /></Field>
      <Field label="وضعیت اولیه"><select value={status} onChange={(event) => setStatus(event.target.value as UserStatus)}><option value="active">فعال</option><option value="inactive">غیرفعال</option></select></Field>
      <Field label="نقش‌های دسترسی" full required>
        <div className="account-role-picker">
          <div className="account-role-picker__heading"><span><strong>{roleIds.length.toLocaleString('en-US')} نقش انتخاب‌شده</strong><small>دسترسی‌های حساب از مجموع مجوزهای همین نقش‌ها محاسبه می‌شوند.</small></span><b>{activeRoles.length.toLocaleString('en-US')} نقش فعال</b></div>
          {selectedRoles.length > 0 && <div className="account-role-picker__selected" aria-label="نقش‌های انتخاب‌شده">{selectedRoles.map((role) => <button type="button" key={role.id} onClick={() => toggleRole(role.id, false)} aria-label={`حذف نقش ${role.name}`} title={`حذف نقش ${role.name}`}><Check size={13}/>{role.name}<X size={13}/></button>)}</div>}
          <label className="compact-role-search account-role-picker__search"><Search size={17}/><input aria-label="جست‌وجوی نقش دسترسی" value={roleQuery} onChange={(event) => setRoleQuery(event.target.value)} placeholder="جست‌وجو در نام یا شرح نقش…" />{roleQuery && <button type="button" onClick={() => setRoleQuery('')} aria-label="پاک‌کردن جست‌وجوی نقش"><X size={15}/></button>}</label>
          <div className="registration-role-list account-role-picker__list" role="group" aria-label="فهرست نقش‌های فعال">
            {visibleRoles.map((role) => <label key={role.id} className={roleIds.includes(role.id) ? 'selected' : ''}>
              <input type="checkbox" checked={roleIds.includes(role.id)} onChange={(event) => toggleRole(role.id, event.target.checked)} />
              <span>{roleIds.includes(role.id) && <Check size={13}/>}</span>
              <div><strong>{role.name}</strong><small>{role.description}</small></div>
              <b>{role.permissions.length.toLocaleString('en-US')} مجوز</b>
            </label>)}
            {!visibleRoles.length && <p>نقشی با این عبارت پیدا نشد.</p>}
          </div>
        </div>
      </Field>
    </FormGrid>
    <div className="dialog-actions"><button className="button button--secondary" onClick={onClose}>انصراف</button><button className="button button--primary" onClick={submit}>ایجاد و اتصال حساب</button></div>
  </Modal>;
}

function salesLevelLabel(value?: SalesHierarchyLevel) { return SALES_LEVELS.find((item) => item.id === value)?.label ?? ''; }
function salesChannelLabel(value?: SalesChannel) { return SALES_CHANNELS.find((item) => item.id === value)?.label ?? ''; }
function personnelName(state: FoundationState, id?: string) { const person = state.personnel.find((item) => item.id === id); return person ? `${person.firstName} ${person.lastName}` : ''; }
function salesStructureLabel(state: FoundationState, id?: string) {const structure = state.salesStructures.find((item) => item.id === id); if (!structure) return 'تعیین نشده'; const branch = state.units.find((item) => item.id === structure.branchUnitId)?.name; return `${salesStructureSupervisorName(structure, state.personnel)}${branch ? ` ـ ${branch}` : ''}`;}
function isSalesPersonnel(person: PersonnelRecord, state: FoundationState) { return Boolean(person.salesHierarchyLevel) || Boolean(state.units.find((item) => item.id === person.unitId)?.name.includes('فروش')); }
function isSalesManagementLevel(level?: SalesHierarchyLevel) {return ['sales_vice', 'sales_manager', 'senior_supervisor'].includes(level ?? '');}
function salesBranchUnitIdsForPersonnel(person: PersonnelRecord, state: FoundationState) {
  const managedIds = managedSalesBranchIdsForPersonnel(state, person);
  if (managedIds.length) return managedIds;
  const assigned = person.salesBranchUnitId ?? person.branchUnitId;
  return assigned && state.units.some((unit) => unit.id === assigned && unit.type === 'شعبه' && unit.status === 'active') ? [assigned] : [];
}
function salesBranchNamesForPersonnel(person: PersonnelRecord, state: FoundationState) {return salesBranchUnitIdsForPersonnel(person, state).map((branchId) => state.units.find((unit) => unit.id === branchId)?.name).filter((name): name is string => Boolean(name));}
function emptyPersonnel(state: FoundationState): PersonnelInput { return {personnelCode: nextPersonnelCode(state.personnel), firstName: '', lastName: '', gender: 'unspecified', maritalStatus: 'unspecified', primaryMobile: '', employmentStatus: 'active', employmentType: 'تمام‌وقت', startDate: todayIsoDate(), unitId: state.units.find((item) => item.status === 'active' && item.type !== 'شعبه')?.id ?? '', positionId: state.positions.find((item) => item.status === 'active')?.id ?? '', branchUnitId: state.units.find((item) => item.status === 'active' && item.type === 'شعبه')?.id}; }
function stripPersonnel(record: PersonnelRecord): PersonnelInput { const {id: _id, linkedUserId: _linkedUserId, movements: _movements, salesCompensationHistory: _salesCompensationHistory, createdAt: _createdAt, updatedAt: _updatedAt, ...input} = record; return input; }
function Metric({value, label, icon}: {value: number; label: string; icon: ReactNode}) { return <article><span>{icon}</span><div><strong>{value.toLocaleString('en-US')}</strong><b>{label}</b><small>داده محلی و قابل ممیزی</small></div></article>; }
function FormGrid({children}: {children: ReactNode}) { return <div className="org-form-grid personnel-form-grid">{children}</div>; }
function Field({label, full = false, required = false, system = false, children}: {label: string; full?: boolean; required?: boolean; system?: boolean; children: ReactNode}) { return <label className={`field-label ${full ? 'field-label--full' : ''}`}>{system ? <SystemLabel>{label}</SystemLabel> : required ? <RequiredLabel>{label}</RequiredLabel> : <OptionalLabel>{label}</OptionalLabel>}{children}</label>; }
function Icon({label, tone = 'neutral', onClick, children}: {label: string; tone?: string; onClick: () => void; children: ReactNode}) { return <button type="button" className={`icon-action icon-action--${tone}`} aria-label={label} data-tooltip={label} onClick={onClick}>{children}</button>; }
function Modal({children, onClose, wide = false}: {children: ReactNode; onClose: () => void; wide?: boolean}) { return <div className="modal-layer" role="dialog" aria-modal="true"><button className="modal-scrim" aria-label="بستن" onClick={onClose} /><section className={`modal-card ${wide ? 'modal-card--wide modal-card--record' : ''}`}>{children}</section></div>; }
function Heading({eyebrow, title, text, onClose}: {eyebrow: string; title: string; text: string; onClose: () => void}) { return <div className="modal-heading"><div><span>{eyebrow}</span><h2>{title}</h2><p>{text}</p></div><button className="icon-button" aria-label="بستن پنجره" onClick={onClose}><X size={20} /></button></div>; }
function ConfirmDialog({title, text, confirm, danger, onClose, onConfirm}: {title: string; text: string; confirm: string; danger?: boolean; onClose: () => void; onConfirm: () => void}) { return <Modal onClose={onClose}><div className="danger-symbol"><Power size={27} /></div><div className="centered-modal"><h2>{title}</h2><p>{text}</p><div className="modal-actions modal-actions--center"><button className="button button--secondary" onClick={onClose}>انصراف</button><button className={`button ${danger ? 'button--danger' : 'button--primary'}`} onClick={onConfirm}>{confirm}</button></div></div></Modal>; }
